const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!node_modules' -g '!vendor' -g '!*.lock' | head -80",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"rg -n \"invalid-path|invalidPath|uploadPath|upload path|/upload|uploadFile\" --glob '!node_modules/**' --glob '!vendor/**' --glob '!*.lock' . | head -250",workdir:"/app",max_output_tokens:8000})
]);
for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -print",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"ls -la",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"grep -RIn --exclude-dir=node_modules --exclude-dir=vendor --exclude-dir=.git --exclude='*.lock' -E 'invalid-path|uploadPath|upload path|uploadFile' . | head -250",workdir:"/app",max_output_tokens:10000})
]);
for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

